CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE schools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(160) NOT NULL, slug varchar(100) NOT NULL UNIQUE, logo_path text, motto varchar(250), email varchar(254), phone varchar(80), address text, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE school_settings (school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, key varchar(100) NOT NULL, value text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(school_id,key));
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), email citext NOT NULL, role varchar(30) NOT NULL CHECK(role IN('IT_ADMIN','MANAGEMENT','TEACHER','PARENT')), status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','LOCKED')), password_hash text, must_change_password boolean NOT NULL DEFAULT true, failed_login_attempts integer NOT NULL DEFAULT 0 CHECK(failed_login_attempts>=0), locked_until timestamptz, last_login_at timestamptz, password_changed_at timestamptz, legacy_user_id text, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,email), UNIQUE(school_id,legacy_user_id));
CREATE TABLE refresh_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash char(64) NOT NULL UNIQUE, csrf_hash char(64) NOT NULL, ip_hash char(64), user_agent_hash char(64), expires_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE academic_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), name varchar(100) NOT NULL, start_date date, end_date date, is_current boolean NOT NULL DEFAULT false, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(start_date IS NULL OR end_date IS NULL OR start_date<=end_date), UNIQUE(school_id,name), UNIQUE(school_id,legacy_id));
CREATE UNIQUE INDEX one_current_session_per_school ON academic_sessions(school_id) WHERE is_current;
CREATE TABLE terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), academic_session_id uuid NOT NULL REFERENCES academic_sessions(id), name varchar(100) NOT NULL, start_date date, end_date date, is_current boolean NOT NULL DEFAULT false, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(start_date IS NULL OR end_date IS NULL OR start_date<=end_date), UNIQUE(school_id,academic_session_id,name), UNIQUE(school_id,legacy_id));
CREATE UNIQUE INDEX one_current_term_per_school ON terms(school_id) WHERE is_current;
CREATE TABLE classes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), name varchar(100) NOT NULL, sort_order integer NOT NULL DEFAULT 0, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,name), UNIQUE(school_id,legacy_id));
CREATE TABLE class_arms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), class_id uuid NOT NULL REFERENCES classes(id), name varchar(100) NOT NULL, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,class_id,name), UNIQUE(school_id,legacy_id));
CREATE TABLE subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), code varchar(40) NOT NULL, name varchar(140) NOT NULL, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,code), UNIQUE(school_id,legacy_id));
CREATE TABLE assessment_structures (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), code varchar(40) NOT NULL, name varchar(140) NOT NULL, category varchar(100) NOT NULL, maximum_score numeric(8,2) NOT NULL CHECK(maximum_score>0), weight numeric(5,2) NOT NULL CHECK(weight BETWEEN 0 AND 100), status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,code), UNIQUE(school_id,legacy_id));
CREATE TABLE grading_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), grade varchar(30) NOT NULL, minimum_score numeric(5,2) NOT NULL CHECK(minimum_score>=0), maximum_score numeric(5,2) NOT NULL CHECK(maximum_score<=100), remark varchar(160), sort_order integer NOT NULL, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(minimum_score<=maximum_score), UNIQUE(school_id,grade), UNIQUE(school_id,legacy_id));

CREATE TABLE students (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), admission_number varchar(80) NOT NULL, first_name varchar(100) NOT NULL, middle_name varchar(100), last_name varchar(100) NOT NULL, gender varchar(20), date_of_birth date, admission_date date NOT NULL, admission_session_id uuid REFERENCES academic_sessions(id), class_id uuid NOT NULL REFERENCES classes(id), class_arm_id uuid REFERENCES class_arms(id), status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','GRADUATED','TRANSFERRED','ARCHIVED')), exit_date date, exit_reason text, legacy_id text, version integer NOT NULL DEFAULT 1, created_by uuid REFERENCES users(id), updated_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,admission_number), UNIQUE(school_id,legacy_id), CHECK((status NOT IN('GRADUATED','TRANSFERRED')) OR exit_date IS NOT NULL));
CREATE TABLE parents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), user_id uuid REFERENCES users(id), first_name varchar(100) NOT NULL, middle_name varchar(100), last_name varchar(100) NOT NULL, email varchar(254), phone varchar(80), address text, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,legacy_id));
CREATE TABLE parent_student_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), parent_id uuid NOT NULL REFERENCES parents(id), student_id uuid NOT NULL REFERENCES students(id), relationship varchar(80) NOT NULL, is_primary boolean NOT NULL DEFAULT false, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,parent_id,student_id), UNIQUE(school_id,legacy_id));
CREATE TABLE student_class_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), student_id uuid NOT NULL REFERENCES students(id), academic_session_id uuid NOT NULL REFERENCES academic_sessions(id), from_class_id uuid REFERENCES classes(id), from_class_arm_id uuid REFERENCES class_arms(id), to_class_id uuid NOT NULL REFERENCES classes(id), to_class_arm_id uuid REFERENCES class_arms(id), action varchar(30) NOT NULL CHECK(action IN('ADMISSION','PROMOTION','TRANSFER','GRADUATION','PLACEMENT_CHANGE')), effective_date date NOT NULL, reason text, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), legacy_id text, UNIQUE(school_id,legacy_id));
CREATE TABLE teachers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), user_id uuid REFERENCES users(id), staff_number varchar(80) NOT NULL, first_name varchar(100) NOT NULL, middle_name varchar(100), last_name varchar(100) NOT NULL, email varchar(254), phone varchar(80), status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,staff_number), UNIQUE(school_id,legacy_id));
CREATE TABLE teacher_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), teacher_id uuid NOT NULL REFERENCES teachers(id), academic_session_id uuid NOT NULL REFERENCES academic_sessions(id), term_id uuid REFERENCES terms(id), class_id uuid NOT NULL REFERENCES classes(id), class_arm_id uuid REFERENCES class_arms(id), subject_id uuid REFERENCES subjects(id), assignment_type varchar(30) NOT NULL CHECK(assignment_type IN('CLASS_TEACHER','SUBJECT_TEACHER')), status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','INACTIVE','ARCHIVED')), legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((assignment_type='CLASS_TEACHER' AND subject_id IS NULL) OR (assignment_type='SUBJECT_TEACHER' AND subject_id IS NOT NULL)), UNIQUE(school_id,legacy_id));
CREATE UNIQUE INDEX one_active_class_teacher ON teacher_assignments(school_id,academic_session_id,class_id,COALESCE(class_arm_id,'00000000-0000-0000-0000-000000000000'::uuid)) WHERE assignment_type='CLASS_TEACHER' AND status='ACTIVE';
CREATE UNIQUE INDEX unique_active_subject_assignment ON teacher_assignments(school_id,teacher_id,academic_session_id,COALESCE(term_id,'00000000-0000-0000-0000-000000000000'::uuid),class_id,COALESCE(class_arm_id,'00000000-0000-0000-0000-000000000000'::uuid),subject_id) WHERE assignment_type='SUBJECT_TEACHER' AND status='ACTIVE';

CREATE TABLE assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), structure_id uuid NOT NULL REFERENCES assessment_structures(id), academic_session_id uuid NOT NULL REFERENCES academic_sessions(id), term_id uuid NOT NULL REFERENCES terms(id), class_id uuid NOT NULL REFERENCES classes(id), class_arm_id uuid REFERENCES class_arms(id), subject_id uuid NOT NULL REFERENCES subjects(id), teacher_id uuid REFERENCES teachers(id), name varchar(160) NOT NULL, maximum_score numeric(8,2) NOT NULL CHECK(maximum_score>0), weight numeric(5,2) NOT NULL CHECK(weight BETWEEN 0 AND 100), status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','OPEN','CLOSED','ARCHIVED')), legacy_id text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,legacy_id));
CREATE TABLE scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), assessment_id uuid NOT NULL REFERENCES assessments(id), student_id uuid NOT NULL REFERENCES students(id), score numeric(8,2) NOT NULL CHECK(score>=0), status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','SUBMITTED','ARCHIVED')), entered_by uuid NOT NULL REFERENCES users(id), updated_by uuid NOT NULL REFERENCES users(id), version integer NOT NULL DEFAULT 1, legacy_id text, entered_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,assessment_id,student_id), UNIQUE(school_id,legacy_id));
CREATE TABLE score_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), score_id uuid NOT NULL REFERENCES scores(id), assessment_id uuid NOT NULL REFERENCES assessments(id), student_id uuid NOT NULL REFERENCES students(id), previous_score numeric(8,2), new_score numeric(8,2) NOT NULL, action varchar(30) NOT NULL, changed_by uuid NOT NULL REFERENCES users(id), changed_at timestamptz NOT NULL DEFAULT now(), reason text, legacy_id text, UNIQUE(school_id,legacy_id));

CREATE TABLE result_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), academic_session_id uuid NOT NULL REFERENCES academic_sessions(id), term_id uuid NOT NULL REFERENCES terms(id), class_id uuid NOT NULL REFERENCES classes(id), class_arm_id uuid REFERENCES class_arms(id), subject_id uuid NOT NULL REFERENCES subjects(id), status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','SUBMITTED','REVIEWED','APPROVED','PUBLISHED')), version integer NOT NULL DEFAULT 1, calculated_by uuid REFERENCES users(id), calculated_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), legacy_id text, UNIQUE NULLS NOT DISTINCT(school_id,academic_session_id,term_id,class_id,class_arm_id,subject_id), UNIQUE(school_id,legacy_id));
CREATE TABLE results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), batch_id uuid NOT NULL REFERENCES result_batches(id), student_id uuid NOT NULL REFERENCES students(id), continuous_assessment_total numeric(8,2) NOT NULL DEFAULT 0, examination_score numeric(8,2) NOT NULL DEFAULT 0, total_score numeric(8,2) NOT NULL DEFAULT 0, total_weighted_score numeric(8,2) NOT NULL, percentage numeric(5,2) NOT NULL CHECK(percentage BETWEEN 0 AND 100), grade varchar(30) NOT NULL, remark varchar(160), status varchar(20) NOT NULL CHECK(status IN('DRAFT','SUBMITTED','REVIEWED','APPROVED','PUBLISHED')), version integer NOT NULL DEFAULT 1, legacy_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,batch_id,student_id), UNIQUE(school_id,legacy_id));
CREATE TABLE result_workflow_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), batch_id uuid NOT NULL REFERENCES result_batches(id), from_status varchar(20), to_status varchar(20) NOT NULL, action_by uuid NOT NULL REFERENCES users(id), action_at timestamptz NOT NULL DEFAULT now(), comment text, legacy_id text, UNIQUE(school_id,legacy_id));
CREATE TABLE warnings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), student_id uuid NOT NULL REFERENCES students(id), academic_session_id uuid REFERENCES academic_sessions(id), term_id uuid REFERENCES terms(id), subject_id uuid REFERENCES subjects(id), warning_type varchar(50) NOT NULL, risk_level varchar(20) NOT NULL CHECK(risk_level IN('LOW','MODERATE','HIGH','CRITICAL')), description text NOT NULL, detected_value text, threshold_value text, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','RESOLVED')), generated_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), legacy_id text, UNIQUE(school_id,legacy_id));
CREATE TABLE academic_recommendations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), student_id uuid NOT NULL REFERENCES students(id), warning_id uuid REFERENCES warnings(id), recommendation_type varchar(50) NOT NULL, recommendation_text text NOT NULL, status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','COMPLETED','ARCHIVED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), legacy_id text, UNIQUE(school_id,legacy_id));
CREATE TABLE report_cards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), student_id uuid NOT NULL REFERENCES students(id), academic_session_id uuid NOT NULL REFERENCES academic_sessions(id), term_id uuid NOT NULL REFERENCES terms(id), status varchar(20) NOT NULL DEFAULT 'GENERATED' CHECK(status IN('GENERATED','PUBLISHED','ARCHIVED')), storage_provider varchar(30) NOT NULL DEFAULT 'LOCAL', storage_key text NOT NULL, file_name varchar(240) NOT NULL, mime_type varchar(100) NOT NULL DEFAULT 'application/pdf', checksum char(64) NOT NULL, generated_by uuid NOT NULL REFERENCES users(id), generated_at timestamptz NOT NULL DEFAULT now(), published_by uuid REFERENCES users(id), published_at timestamptz, emailed_at timestamptz, version integer NOT NULL DEFAULT 1, legacy_id text, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,student_id,academic_session_id,term_id), UNIQUE(school_id,legacy_id));

CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid REFERENCES schools(id), user_id uuid REFERENCES users(id), action varchar(100) NOT NULL, entity_type varchar(80), entity_id uuid, old_value jsonb, new_value jsonb, ip_hash char(64), user_agent_hash char(64), request_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sync_operations (id uuid PRIMARY KEY, school_id uuid NOT NULL REFERENCES schools(id), user_id uuid NOT NULL REFERENCES users(id), action varchar(100) NOT NULL, entity_type varchar(80), status varchar(20) NOT NULL CHECK(status IN('PROCESSING','SYNCED','CONFLICT','FAILED')), payload_hash char(64) NOT NULL, result jsonb, error_code varchar(50), created_at timestamptz NOT NULL, processed_at timestamptz, UNIQUE(school_id,user_id,id));
CREATE TABLE offline_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), user_id uuid NOT NULL REFERENCES users(id), device_fingerprint_hash char(64) NOT NULL, enabled_at timestamptz NOT NULL DEFAULT now(), last_sync_at timestamptz, revoked_at timestamptz, UNIQUE(school_id,user_id,device_fingerprint_hash));

CREATE INDEX users_school_role_status_idx ON users(school_id,role,status);
CREATE INDEX students_school_class_status_idx ON students(school_id,class_id,class_arm_id,status);
CREATE INDEX students_school_name_idx ON students(school_id,last_name,first_name);
CREATE INDEX parents_school_user_idx ON parents(school_id,user_id);
CREATE INDEX parent_links_parent_status_idx ON parent_student_links(school_id,parent_id,status);
CREATE INDEX parent_links_student_status_idx ON parent_student_links(school_id,student_id,status);
CREATE INDEX teacher_assignments_scope_idx ON teacher_assignments(school_id,teacher_id,academic_session_id,term_id,status);
CREATE INDEX assessments_scope_idx ON assessments(school_id,academic_session_id,term_id,class_id,class_arm_id,subject_id,status);
CREATE INDEX scores_assessment_updated_idx ON scores(school_id,assessment_id,updated_at);
CREATE INDEX score_history_score_idx ON score_history(school_id,score_id,changed_at);
CREATE INDEX result_batches_workflow_idx ON result_batches(school_id,status,academic_session_id,term_id);
CREATE INDEX results_student_period_idx ON results(school_id,student_id,updated_at);
CREATE INDEX warnings_student_status_idx ON warnings(school_id,student_id,status);
CREATE INDEX reports_student_period_idx ON report_cards(school_id,student_id,academic_session_id,term_id,status);
CREATE INDEX audit_school_time_idx ON audit_logs(school_id,created_at DESC);
CREATE INDEX audit_entity_idx ON audit_logs(school_id,entity_type,entity_id);
CREATE INDEX refresh_sessions_user_active_idx ON refresh_sessions(user_id,expires_at) WHERE revoked_at IS NULL;
CREATE INDEX sync_operations_user_status_idx ON sync_operations(school_id,user_id,status,created_at);

CREATE OR REPLACE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['schools','users','academic_sessions','terms','classes','class_arms','subjects','assessment_structures','grading_rules','students','parents','parent_student_links','teachers','teacher_assignments','assessments','scores','result_batches','results','warnings','academic_recommendations','report_cards'] LOOP EXECUTE format('CREATE TRIGGER %I_touch BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION touch_updated_at()',t,t); END LOOP; END $$;
